    /// <summary>Looks up an exact key or a nonempty template expansion using ordinal matching.</summary>
    public static bool TryGetAttribute(string key,
        [global::System.Diagnostics.CodeAnalysis.NotNullWhen(true)] out RegistryAttributeInfo? attribute)
    {
        if (Attributes.TryGetValue(key, out attribute)) return true;
        foreach (var template in Templates)
        {
            if (key.Length > template.Prefix.Length && key.StartsWith(template.Prefix, global::System.StringComparison.Ordinal))
            {
                attribute = template.Info;
                return true;
            }
        }

        attribute = null;
        return false;
    }

    /// <summary>Looks up a metric definition; an unregistered custom metric returns false.</summary>
    public static bool TryGetMetric(string name,
        [global::System.Diagnostics.CodeAnalysis.NotNullWhen(true)] out RegistryMetricInfo? metric) =>
        Metrics.TryGetValue(name, out metric);
